const updateAttempt = `-- name: UpdateAttempt :execrows
UPDATE payments.payment_attempts SET
  status = $2, failure_code = $3, failure_retryable = $4, provider_raw_code = $5, resolution = $6, resolved_by = $7,
  resolve_note = $8, check_count = $9, last_checked_at = $10, finalized_at = $11, version = version + 1, updated_at = $12
WHERE id = $1 AND version = $13
`

type UpdateAttemptParams struct {
	ID               uuid.UUID
	Status           string
	FailureCode      *string
	FailureRetryable *bool
	ProviderRawCode  *string
	Resolution       *string
	ResolvedBy       *string
	ResolveNote      *string
	CheckCount       int32
	LastCheckedAt    *time.Time
	FinalizedAt      *time.Time
	UpdatedAt        time.Time
	Version          int32
}

func (q *Queries) UpdateAttempt(ctx context.Context, arg UpdateAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAttempt,
		arg.ID,
		arg.Status,
		arg.FailureCode,
		arg.FailureRetryable,
		arg.ProviderRawCode,
		arg.Resolution,
		arg.ResolvedBy,
		arg.ResolveNote,
		arg.CheckCount,
		arg.LastCheckedAt,
		arg.FinalizedAt,
		arg.UpdatedAt,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

